/// <reference lib="webworker" />
declare let self: ServiceWorkerGlobalScope;

import { precacheAndRoute } from 'workbox-precaching';
import { clientsClaim } from 'workbox-core';

// Firebase scripts need to be imported via importScripts in the SW
importScripts('https://www.gstatic.com/firebasejs/10.7.1/firebase-app-compat.js');
importScripts('https://www.gstatic.com/firebasejs/10.7.1/firebase-messaging-compat.js');

self.skipWaiting();
clientsClaim();

// Precache the assets generated by Vite
precacheAndRoute(self.__WB_MANIFEST);

// Initialize Firebase
const firebaseConfig = {
  apiKey: "AIzaSyCnzDtAhfGJtCps33cOXcjMqQ1QCnoPEdU",
  authDomain: "gastosapp-druizinho.firebaseapp.com",
  projectId: "gastosapp-druizinho",
  storageBucket: "gastosapp-druizinho.firebasestorage.app",
  messagingSenderId: "757888333827",
  appId: "1:757888333827:web:1703a8f4322697beb53636",
  measurementId: "G-8RFFJLVZEB"
};

(self as any).firebase.initializeApp(firebaseConfig);
const messaging = (self as any).firebase.messaging();

messaging.onBackgroundMessage((payload: any) => {
  console.log('[sw.ts] Received background message', payload);
  
  // On some Android devices, Firebase doesn't auto-show a notification
  // when the payload has both `notification` and `data` fields.
  // We manually show it to guarantee delivery.
  const title = payload.notification?.title || payload.data?.title || 'GastosApp';
  const body = payload.notification?.body || payload.data?.body || '';
  const url = payload.fcmOptions?.link || payload.data?.url || '/';

  self.registration.showNotification(title, {
    body,
    icon: '/pwa-192x192.png',
    badge: '/favicon.svg',
    data: { url },
  });
});

self.addEventListener('notificationclick', (event: any) => {
  event.notification.close();

  // URL comes from the data object we set in showNotification above,
  // or from FCM's fcm_options.link field on auto-displayed notifications.
  const targetUrl = event.notification.data?.url || '/';

  event.waitUntil(
    (self as any).clients.matchAll({ type: 'window', includeUncontrolled: true }).then((clientList: any[]) => {
      // If there's already a window open with this app, focus it and navigate
      for (const client of clientList) {
        if ('focus' in client) {
          client.focus();
          if ('navigate' in client) client.navigate(targetUrl);
          return;
        }
      }
      // Otherwise open a new window
      return (self as any).clients.openWindow(targetUrl);
    })
  );
});

